INSERT INTO commission_tiers(scheme_id,tier_order,minimum_monthly_sales,maximum_monthly_sales,commission_rate) SELECT id,3,70000,79999,0.07 FROM commission_schemes WHERE code='DEFAULT' AND version=1 ON CONFLICT DO NOTHING;
INSERT INTO commission_tiers(scheme_id,tier_order,minimum_monthly_sales,maximum_monthly_sales,commission_rate) SELECT id,4,80000,89999,0.08 FROM commission_schemes WHERE code='DEFAULT' AND version=1 ON CONFLICT DO NOTHING;
INSERT INTO commission_tiers(scheme_id,tier_order,minimum_monthly_sales,maximum_monthly_sales,commission_rate) SELECT id,5,90000,NULL,0.10 FROM commission_schemes WHERE code='DEFAULT' AND version=1 ON CONFLICT DO NOTHING;
